BEGIN;
SET LOCAL lock_timeout='5min';
SET LOCAL statement_timeout='15min';
SELECT pg_advisory_xact_lock(84746003);
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE OR REPLACE FUNCTION public.hsd_commercial_current_tenant() RETURNS text LANGUAGE sql STABLE AS $$
 SELECT coalesce(auth.jwt()->>'tenant_id',auth.jwt()->'app_metadata'->>'tenant_id',auth.jwt()->'user_metadata'->>'tenant_id');
$$;
DO $$ BEGIN IF to_regclass('public.hsd_service_categories') IS NULL THEN RAISE EXCEPTION 'UMZ1 baseline missing'; END IF; IF to_regclass('public.hsd_technical_plan_versions') IS NULL THEN RAISE EXCEPTION 'UMZ2 baseline missing'; END IF; END $$;
CREATE TABLE IF NOT EXISTS public.hsd_commercial_requests (id uuid primary key default gen_random_uuid(),tenant_id text not null,code text not null,title text not null,universe text not null check(universe in ('b2c','b2b')),status text not null default 'draft',technical_plan_id uuid not null references public.hsd_technical_plans(id),technical_plan_version_id uuid not null references public.hsd_technical_plan_versions(id),category_id uuid references public.hsd_service_categories(id),customer_segment text not null,commercial_objective text not null,scenario_count int not null default 1 check(scenario_count between 1 and 10),constraints jsonb not null default '{}',created_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code));
