DROP POLICY IF EXISTS hsd_commercial_requests_tenant_select ON public.hsd_commercial_requests;
CREATE POLICY hsd_commercial_requests_tenant_select ON public.hsd_commercial_requests FOR SELECT USING (tenant_id = public.hsd_commercial_current_tenant());
