CREATE OR REPLACE FUNCTION public.hsd_commercial_immutable_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable commercial record'; END $$;
DO $$ DECLARE x text; BEGIN FOREACH x IN ARRAY ARRAY['hsd_offer_versions','hsd_offer_calculations','hsd_bundle_versions','hsd_bundle_calculations','hsd_sellable_versions','hsd_sellable_prices','hsd_sellable_publications','hsd_sellable_status_events','hsd_sellable_document_versions'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS trg_%I_immutable ON public.%I',x,x); EXECUTE format('CREATE TRIGGER trg_%I_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.hsd_commercial_immutable_guard()',x,x); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.hsd_sellable_mutation_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.status IN ('published','superseded','retired') AND (
 NEW.code IS DISTINCT FROM OLD.code OR NEW.commercial_name IS DISTINCT FROM OLD.commercial_name OR NEW.technical_name IS DISTINCT FROM OLD.technical_name OR NEW.universe IS DISTINCT FROM OLD.universe OR NEW.category_id IS DISTINCT FROM OLD.category_id OR NEW.technical_plan_version_id IS DISTINCT FROM OLD.technical_plan_version_id OR NEW.offer_id IS DISTINCT FROM OLD.offer_id OR NEW.bundle_id IS DISTINCT FROM OLD.bundle_id OR NEW.active_version IS DISTINCT FROM OLD.active_version OR NEW.promise IS DISTINCT FROM OLD.promise OR NEW.calculation_snapshot IS DISTINCT FROM OLD.calculation_snapshot OR NEW.readiness IS DISTINCT FROM OLD.readiness
 ) THEN RAISE EXCEPTION 'Published sellable content is immutable; create a new version'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_hsd_sellables_immutable_published ON public.hsd_sellables; CREATE TRIGGER trg_hsd_sellables_immutable_published BEFORE UPDATE ON public.hsd_sellables FOR EACH ROW EXECUTE FUNCTION public.hsd_sellable_mutation_guard();
CREATE OR REPLACE VIEW public.hsd_commercial_price_books_v WITH (security_invoker=true) AS SELECT pb.id,pb.tenant_id,pb.code,pb.name,pb.universe,pb.status,pb.current_version version_number,v.effective_from,v.effective_to,count(e.id)::int entry_count FROM public.hsd_commercial_price_books pb LEFT JOIN public.hsd_commercial_price_book_versions v ON v.price_book_id=pb.id AND v.version_number=pb.current_version LEFT JOIN public.hsd_commercial_price_entries e ON e.price_book_version_id=v.id GROUP BY pb.id,v.effective_from,v.effective_to;
CREATE OR REPLACE VIEW public.hsd_sellable_registry_v WITH (security_invoker=true) AS SELECT s.id,s.tenant_id,s.code,s.commercial_name,s.technical_name,s.universe,s.status,s.category_id,s.active_version,s.promise,s.readiness,s.published_at,s.created_at,p.starting_price,p.margin_percent FROM public.hsd_sellables s LEFT JOIN public.hsd_sellable_versions v ON v.sellable_id=s.id AND v.version_number=s.active_version LEFT JOIN public.hsd_sellable_prices p ON p.sellable_version_id=v.id;
GRANT SELECT ON public.hsd_commercial_price_books_v,public.hsd_sellable_registry_v TO authenticated;
